import jakarta.persistence.MappedSuperclass;
import jakarta.persistence.PostLoad;
import jakarta.persistence.PostPersist;
import jakarta.persistence.Transient;
import org.springframework.data.domain.Persistable;

@MappedSuperclass
abstract class BaseEntity<ID> implements Persistable<ID> {

    @Transient
    private boolean isNew = true;

    @Override
    public boolean isNew() {
        return isNew;
    }

    // Sau khi entity duoc luu lan dau hoac duoc load tu DB, danh dau la "khong con moi".
    @PostPersist
    @PostLoad
    void markNotNew() {
        this.isNew = false;
    }
}

import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpStatus;
import org.springframework.http.HttpStatusCode;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.context.request.WebRequest;
import org.springframework.web.servlet.mvc.method.annotation.ResponseEntityExceptionHandler;

import java.util.List;
import java.util.stream.Collectors;

// Nhom (3) - xung dot du lieu (vi du email da ton tai luc Register, xem Day
// 33/day33-blk-24): anh xa rieng sang 409 Conflict, KHONG dung chung voi
// ValidationException (nhom (2) luon anh xa 400).
class ConflictException extends RuntimeException {
    ConflictException(String message) { super(message); }
}

// Ke thua ResponseEntityExceptionHandler de tai dung co che xu ly loi mac
// dinh cua Spring MVC (gom ca MethodArgumentNotValidException) va chi can
// override method can tuy chinh phan body tra ve.
@RestControllerAdvice
class GlobalExceptionHandler extends ResponseEntityExceptionHandler {

    // Nhom (1) - loi tu dong tu @Valid tren @RequestBody: override method co
    // san cua ResponseEntityExceptionHandler de doi dinh dang loi sang
    // ProblemDetail kem danh sach FieldError, thay vi dung body mac dinh.
    @Override
    protected ResponseEntity<Object> handleMethodArgumentNotValid(
            MethodArgumentNotValidException ex, HttpHeaders headers,
            HttpStatusCode status, WebRequest request) {
        ProblemDetail problem = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "Du lieu khong hop le");
        List<String> errors = ex.getBindingResult().getFieldErrors().stream()
                .map(fe -> fe.getField() + ": " + fe.getDefaultMessage())
                .collect(Collectors.toList());
        problem.setProperty("errors", errors);
        return ResponseEntity.status(HttpStatus.BAD_REQUEST).body(problem);
    }

    @ExceptionHandler(ResourceNotFoundException.class)
    ProblemDetail handleNotFound(ResourceNotFoundException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
    }

    // Nhom (2) - ValidationException la exception nghiep vu TU DINH NGHIA,
    // tang service tu nem tuong minh cho quy tac khong bieu dien duoc bang
    // annotation Bean Validation; chi mang mot message nghiep vu don, khong
    // co danh sach FieldError nhu nhom (1).
    @ExceptionHandler(ValidationException.class)
    ProblemDetail handleValidation(ValidationException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, ex.getMessage());
    }

    // Nhom (3) - xung dot du lieu, vi du email da ton tai luc Register (Day
    // 33/day33-blk-24) - anh xa 409 Conflict theo dung API contract Day 31.
    @ExceptionHandler(ConflictException.class)
    ProblemDetail handleConflict(ConflictException ex) {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, ex.getMessage());
    }
}
